// v37.xx (cw-m1rankui), critic on the Mainframe and stats screens (P1): labels were 13px under the 16px floor and lime showed three times. Labels 16px,
// values 30px in white, the next rank and reward in white; lime is the bar fill only (8px on the line colour).
lab='font-size:16px;letter-spacing:.04em;color:var(--ash);line-height:20px';
el.innerHTML=
  '<div style="flex:none;min-width:190px"><div style="'+lab+'">rank</div><div id="rankname" style="font-size:30px;line-height:36px;font-weight:700;letter-spacing:.02em;color:var(--bone)">'+R.n+'</div></div>'+
  '<div style="flex:none;min-width:190px"><div style="'+lab+'">lifetime earnings</div><div id="rankearn" style="font-size:30px;line-height:36px;font-weight:700;color:var(--bone)">$'+le.toLocaleString()+'</div></div>'+
  '<div style="flex:1;min-width:0">'+
    '<div style="display:flex;justify-content:space-between;gap:12px;'+lab+'"><span>next  <b id="ranknext" style="color:var(--bone);font-weight:600">'+(N?(N.n+'  $'+N.need.toLocaleString()):'top rank')+'</b></span>'+
    (N?('<span>reward  <b id="rankrw" style="color:var(--bone);font-weight:600">'+rankRwTxt(N.rw)+'</b></span>'):'')+'</div>'+
    '<div style="height:8px;margin-top:10px;border:1px solid var(--ui-line-hi);border-radius:2px;background:rgba(0,0,0,.35)"><div id="rankfill" style="height:100%;width:'+(f*100).toFixed(1)+'%;background:var(--amber)"></div></div>'+
  '</div>';

check:
{v:'VER',what:'cw-m1rankui, critic on the Mainframe rank strip (P1 both screens: labels about 13px under the 16px floor, lime three times): every text in the strip is 16px or more, no text in it is lime, and lime is the bar fill only',
 run:function(){
   if(!(window.__runPrep&&window.__resetCfg&&window.__pinDefaults&&window.__cleanProfile)) return 'SKIP: this fixture cannot stage';
   if(typeof openOps!=='function'||typeof renderRank!=='function'||typeof RANKS==='undefined') return 'SKIP: no rank strip here';
   var saved=P, oldStore=storeSet, oldSave=saveProfile, bad=[], el, all, i, e, cs, amb, tmp, own, n=0;
   function need(ok,msg){ if(!ok) bad.push(msg); }
   try{
     __runPrep(); __topClear(); __resetCfg(); __pinDefaults(0); __cleanProfile();
     P=JSON.parse(JSON.stringify(saved)); storeSet=function(){}; saveProfile=function(){};
     P.lifeEarn=RANKS[1].need+5000; delete P.sellDay; P.rankPaid=[0,1]; P.mig1r=1;
     openOps('con');
     el=document.getElementById('rankstrip');
     if(!el||!(el.getBoundingClientRect().height>0)) return 'the Mainframe rank strip is not on screen';
     tmp=document.createElement('div'); tmp.style.color='var(--amber)'; el.appendChild(tmp); amb=getComputedStyle(tmp).color; el.removeChild(tmp);
     all=el.querySelectorAll('*');
     for(i=0;i<all.length;i++){
       e=all[i]; own=''; [].forEach.call(e.childNodes,function(c){ if(c.nodeType===3) own+=c.textContent; });
       if(!own.trim()) continue;
       n++; cs=getComputedStyle(e);
       need(parseFloat(cs.fontSize)>=16,'"'+own.trim()+'" is '+cs.fontSize+', under 16px');
       need(cs.color!==amb,'"'+own.trim()+'" is lime');
     }
     need(n>=6,'only '+n+' texts in the strip');
     e=document.getElementById('rankfill');
     need(e&&getComputedStyle(e).backgroundColor===amb,'the bar fill is not lime');
   }catch(x){ bad.push('threw: '+(x&&x.message||x)); }
   finally{ P=saved; storeSet=oldStore; saveProfile=oldSave; try{ __topClear(); __cleanProfile(); }catch(_c){} }
   return bad.length?bad.join('; '):null; }},
